#include <stdio.h>
#include <mpfr.h>
int main(void) {
    mpfr_set_default_prec(256);
    mpfr_t alpha, m_eV, hbarc, hbars, em, B, R, z, c, s, t1, t2, num, den, F, mR, shift;
    mpfr_inits(alpha,m_eV,hbarc,hbars,em,B,R,z,c,s,t1,t2,num,den,F,mR,shift,NULL);
    mpfr_set_str(alpha,\"7.2973525643e-3\",10,MPFR_RNDN);
    mpfr_set_str(m_eV,\"510998.95000\",10,MPFR_RNDN);
    mpfr_set_str(hbarc,\"1.973269804e-5\",10,MPFR_RNDN);
    mpfr_set_str(hbars,\"6.582119569e-16\",10,MPFR_RNDN);
    mpfr_set_str(em,\"1.75882001076e11\",10,MPFR_RNDN);
    mpfr_set_str(B,\"5.0\",10,MPFR_RNDN);
    mpfr_set_str(R,\"1.0\",10,MPFR_RNDN);
    mpfr_mul(z,hbars,em,MPFR_RNDN); mpfr_mul(z,z,B,MPFR_RNDN); mpfr_mul(z,z,R,MPFR_RNDN); mpfr_div(z,z,hbarc,MPFR_RNDN);
    mpfr_sin_cos(s,c,z,MPFR_RNDN);
    mpfr_mul(t1,z,z,MPFR_RNDN); mpfr_ui_sub(t1,1,t1,MPFR_RNDN);
    mpfr_mul(num,t1,c,MPFR_RNDN); mpfr_mul(t2,z,s,MPFR_RNDN); mpfr_add(num,num,t2,MPFR_RNDN);
    mpfr_mul(den,t1,s,MPFR_RNDN); mpfr_mul(t2,z,c,MPFR_RNDN); mpfr_sub(den,den,t2,MPFR_RNDN);
    mpfr_div(F,num,den,MPFR_RNDN); mpfr_mul(F,F,z,MPFR_RNDN); mpfr_mul_ui(F,F,2,MPFR_RNDN); mpfr_div_ui(F,F,3,MPFR_RNDN);
    mpfr_mul(t1,z,z,MPFR_RNDN); mpfr_ui_div(t1,1,t1,MPFR_RNDN); mpfr_add(F,F,t1,MPFR_RNDN);
    mpfr_mul(mR,m_eV,R,MPFR_RNDN); mpfr_div(mR,mR,hbarc,MPFR_RNDN);
    mpfr_div(shift,alpha,mR,MPFR_RNDN); mpfr_mul(shift,shift,F,MPFR_RNDN);
    mpfr_printf(\"z = %.40Re\\nF = %.40Re\\nshift = %.40Re\\n\",z,F,shift);
    return 0;
}
EOF
