from fractions import Fraction
Lx,Ly=3,2
siteid={}; edges=[]
for nx in range(Lx):
 for ny in range(Ly):
  for lab,dz in enumerate([((nx+1)%Lx,ny,1),(nx,(ny+1)%Ly,1),(nx,ny,1)]):
   A=(nx,ny,0); B=dz
   for s in (A,B): siteid.setdefault(s,len(siteid))
   edges.append((lab,siteid[A],siteid[B]))
N=len(siteid)
# bond operators: prefactor cdots state direction sign and destination.
def seq_coeff(sites,ops,state):
    coeff=Fraction(1)
    for s,op in zip(sites,ops):
      b=(state>>s)&1
      if op=='Z':
       if b: coeff=-coeff
      elif op in 'XY':
       if op=='Y': coeff *= Fraction(1-2*b,1)
       state "'^= 1<<s
    return coeff,state
plaquettes=[]
for nx in range(Lx):
 for ny in range(Ly):
  ss=[((nx+1)%Lx,ny,0),((nx+1)%Lx,(ny+1)%Ly,1),(nx,(ny+1)%Ly,0),
      ((nx-1)%Lx,(ny-1)%Ly,1),((nx-1)%Lx,(ny-1)%Ly,0),(nx,(ny-1)%Ly,1)]
  operator='"'YZXYZX'
  plaquettes.append(([siteid[s] for s in ss],operator))
